```javascript
const N = parseInt(require('fs').readFileSync('/dev/stdin', 'utf8').trim(), 10);

const dp = new Array(N + 1).fill(0);
for (let i = 1; i <= N; i++) {
    let best = Infinity;
    let x = i;
    while (x > 0) {
        const d = x % 10;
        x = Math.floor(x / 10);
        if (d > 0 && dp[i - d] + 1 < best) {
            best = dp[i - d] + 1;
        }
    }
    dp[i] = best;
}

console.log(dp[N]);
